import React, { PropsWithChildren, useMemo } from 'react';

import { AnnotationsDataContext } from '../contexts/AnnotationsDataContext.js';
import { processAnnotationTracksData } from '../functions/process-annotation-tracks-data.js';
import { TrackProps } from '../types/tracks.js';

interface AnnotationsDataProviderProps {
  tracks: TrackProps[];
}

export const AnnotationsDataProvider = ({
  tracks,
  children,
}: PropsWithChildren<AnnotationsDataProviderProps>) => {
  const derivedData = useMemo(() => {
    const tooltipGrouping = tracks.map(
      ({ markers, color, symbol, label, hidden }) => ({
        markers: processAnnotationTracksData({ markers, color, symbol, label }),
        label,
        hidden,
      }),
    );

    return {
      tooltipGrouping,
    };
  }, [tracks]);

  return (
    <AnnotationsDataContext.Provider value={derivedData}>
      {children}
    </AnnotationsDataContext.Provider>
  );
};
